import re

_UNITS = (("d", 86_400), ("h", 3_600), ("m", 60), ("s", 1))
_DURATION_RE = re.compile(r"\s*(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?\s*")


def parse_duration(s):
    """Convert a duration such as '1h30m' to an integer number of seconds."""
    match = _DURATION_RE.fullmatch(s)
    if match is None or not any(match.groups()):
        raise ValueError(f"Invalid duration: {s!r}")

    total = 0
    for amount, (_, seconds_per_unit) in zip(match.groups(), _UNITS):
        if amount is not None:
            total += int(amount) * seconds_per_unit
    return total
